using System.IO.Compression;using System.Text;using System.Text.RegularExpressions;
public interface IDocumentTextExtractor{Task<string> ExtractAsync(Stream content,string contentType,CancellationToken ct=default);}
public sealed class DocumentTextExtractor(IConfiguration configuration,HttpClient http):IDocumentTextExtractor{public async Task<string> ExtractAsync(Stream content,string contentType,CancellationToken ct=default){if(content is null||!content.CanRead)throw new ArgumentException("Readable content is required",nameof(content));if(string.Equals(contentType,"text/plain",StringComparison.OrdinalIgnoreCase))return await new StreamReader(content,Encoding.UTF8,true,1024,true).ReadToEndAsync(ct);if(string.Equals(contentType,"application/vnd.openxmlformats-officedocument.wordprocessingml.document",StringComparison.OrdinalIgnoreCase))return await ExtractDocxAsync(content,ct);if(string.Equals(contentType,"application/pdf",StringComparison.OrdinalIgnoreCase)||string.Equals(contentType,"application/msword",StringComparison.OrdinalIgnoreCase))return await ExtractWithDocumentIntelligenceAsync(content,ct);throw new NotSupportedException($"Unsupported content type: {contentType}");}
static async Task<string> ExtractDocxAsync(Stream stream,CancellationToken ct){using var zip=new ZipArchive(stream,ZipArchiveMode.Read,true);var entry=zip.GetEntry("word/document.xml")??throw new InvalidDataException("DOCX document.xml is missing");await using var s=entry.Open();using var reader=new StreamReader(s,Encoding.UTF8);var xml=await reader.ReadToEndAsync(ct);return Regex.Replace(System.Net.WebUtility.HtmlDecode(Regex.Replace(xml,"<[^>]+>"," ")),"\\s+"," ").Trim();}
async Task<string> ExtractWithDocumentIntelligenceAsync(Stream stream,CancellationToken ct){var endpoint=configuration["Ingestion:DocumentIntelligenceEndpoint"]?.TrimEnd('/');var key=configuration["Ingestion:DocumentIntelligenceKey"];if(string.IsNullOrWhiteSpace(endpoint)||string.IsNullOrWhiteSpace(key))throw new InvalidOperationException("Document Intelligence configuration is required for PDF/DOC extraction");using var request=new HttpRequestMessage(HttpMethod.Post,$"{endpoint}/documentintelligence/documentModels/prebuilt-read:analyze?api-version=2024-11-30");request.Headers.Add("Ocp-Apim-Subscription-Key",key);request.Content=new StreamContent(stream);request.Content.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue("application/octet-stream");using var response=await http.SendAsync(request,ct);response.EnsureSuccessStatusCode();if(!response.Headers.TryGetValues("Operation-Location",out var values))throw new InvalidOperationException("Document Intelligence did not return Operation-Location");var location=values.Single();for(var i=0;i<30;i++){await Task.Delay(TimeSpan.FromSeconds(2),ct);using var poll=new HttpRequestMessage(HttpMethod.Get,location);poll.Headers.Add("Ocp-Apim-Subscription-Key",key);using var result=await http.SendAsync(poll,ct);result.EnsureSuccessStatusCode();var json=await result.Content.ReadAsStringAsync(ct);using var doc=System.Text.Json.JsonDocument.Parse(json);var status=doc.RootElement.GetProperty("status").GetString();if(string.Equals(status,"succeeded",StringComparison.OrdinalIgnoreCase))return doc.RootElement.GetProperty("analyzeResult").GetProperty("content").GetString()??string.Empty;if(string.Equals(status,"failed",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Document Intelligence extraction failed");}throw new TimeoutException("Document Intelligence extraction timed out");}}